#!/usr/bin/env python3
"""crispr/in_vivo_delivery_planner — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "in_vivo_delivery_planner"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'in_vivo_delivery_planner', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """LNP / AAV delivery 选择规则(基于 target tissue + cargo size)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    tissue = (payload.get("target_tissue") or "").lower()
    cargo_size_kb = float(payload.get("cargo_size_kb", 0))
    cargo_type = (payload.get("cargo_type") or "").lower()
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tissue": tissue, "cargo_kb": cargo_size_kb, "cargo_type": cargo_type}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not tissue:
        return {"ok": False, "error": "需要 target_tissue", "diagnostics": diagnostics}
    rules = []
    if cargo_size_kb < 4.7:
        if tissue in ("muscle", "skeletal_muscle"): rules.append({"vector": "AAV9", "rationale": "AAV9 高 muscle tropism"})
        if tissue in ("liver", "hepatocyte"): rules.append({"vector": "AAV8", "rationale": "AAV8 高 liver tropism"})
        if tissue in ("cns", "brain", "neuron"): rules.append({"vector": "AAV9-PHP.eB", "rationale": "CNS 穿透 BBB"})
        if tissue in ("retina", "eye"): rules.append({"vector": "AAV2 / AAV8 subretinal", "rationale": "标准眼科 AAV"})
    else:
        rules.append({"vector": "LNP-mRNA", "rationale": "cargo > AAV 容量(~4.7kb),LNP-mRNA 临时表达"})
        if cargo_type == "crispr_rnp":
            rules.append({"vector": "LNP-RNP", "rationale": "RNP 直接递送,免转录"})
    return {"ok": True, "skill_id": SKILL,
            "n_guides": len(rules), "guides_csv": "",
            "best_guide": {"seq": rules[0]["vector"] if rules else "",
                          "cfd_score": 1.0 if rules else 0.0,
                          "mit_score": 1.0 if rules else 0.0},
            "recommendations": rules, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
